const AGENT_BASE_URL = 'https://sltrnddigitallab.app.n8n.cloud/webhook';
// Base URL of your n8n production webhooks (no trailing slash).

const input = $input.first().json;
// The first item coming out of the Webhook node.

const body = input.body || input;
// n8n puts the POST body under .body; fall back to the item itself when testing.

const company = body.company || {};
// The business picked in the dashboard search bar: name, industry, location, overview, address.

const user = body.user || {};
// The logged-in sales rep: name, phone, designation, email (used on the contact block and letter).

const products = Array.isArray(body.selectedProducts) ? body.selectedProducts : [];
// The SLT products the rep ticked for this proposal (name, description, features).

if (!company.name) throw new Error('company.name is required');
// Stop early if no business was sent.

if (products.length === 0) throw new Error('selectedProducts must contain at least one product');
// Stop early if no products were selected.

const ctx = Object.assign({}, body.agentContext || {});
// Results the dashboard already holds from the other agents: customerResearch, meetingPrep, productRecommendations.

const place = company.location || 'Sri Lanka';
// Used to make the agent prompts more specific.

const callAgent = async (path, prompt) => {
  // Calls one of your existing agent webhooks and returns its results array.
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: AGENT_BASE_URL + '/' + path,
    body: { prompt: prompt },
    json: true,
    timeout: 40000
  });
  // Same request shape your Express backend already sends: { prompt }.
  return res && res.results ? res.results : null;
  // Every agent answers { success, results: [...] }.
};

const jobs = {};
// Holds one pending call per agent whose data is missing.

if (!ctx.customerResearch) jobs.customerResearch = callAgent('customer-research', 'Research ' + company.name + ' ' + place);
// Customer Research is only called if the dashboard did not send its result.

if (!ctx.meetingPrep) jobs.meetingPrep = callAgent('meeting-prep', 'Prepare a meeting brief for ' + company.name + ' ' + place);
// Meeting Preparation is only called if missing.

if (!ctx.productRecommendations) jobs.productRecommendations = callAgent('product-recommendation', 'Recommend SLT-Mobitel products for ' + company.name + ' ' + place);
// Product Recommendations is only called if missing.

const keys = Object.keys(jobs);
// Names of the agents we are fetching right now.

const settled = await Promise.allSettled(keys.map(function (k) { return jobs[k]; }));
// Runs the missing agent calls in parallel; one failing agent will not break the proposal.

const fetched = [];
const failed = [];
// Bookkeeping so the frontend can show which data sources were used.

settled.forEach(function (s, i) {
  if (s.status === 'fulfilled' && s.value) { ctx[keys[i]] = s.value; fetched.push(keys[i]); }
  else { failed.push(keys[i]); }
});
// Store each fetched result, or record the failure.

const toText = function (v, max) {
  // Turns any agent output into plain text and trims it so the prompt stays small.
  if (!v) return '';
  // Nothing provided.
  const arr = typeof v === 'string' ? [v] : (Array.isArray(v) ? v : (v.results || [v]));
  // Accept a string, a results array, or the full { results } response.
  const text = arr.map(function (r) {
    if (typeof r === 'string') return r;
    const head = r.Category || r.Section || r.Product || '';
    // Customer Research uses Category, Meeting Prep uses Section, Recommendations use Product.
    const tail = r.Details || r.Content || r['Why Recommended'] || JSON.stringify(r);
    // Matching body field for each agent.
    return head + ': ' + tail;
  }).join('\n\n');
  // One block per section, separated by a blank line.
  return text.length > max ? text.substring(0, max) + ' ...' : text;
  // Hard cap per source to control token use.
};

const now = new Date();
const months = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
const dateStr = String(now.getDate()).padStart(2, '0') + ' ' + months[now.getMonth()] + ' ' + now.getFullYear();
// Date in the template format, for example 12 OCT 2026.

const proposalRef = body.proposalRef || ('1-' + Math.random().toString(36).substring(2, 8).toUpperCase());
// Proposal reference number; the backend can send its own.

const productBlock = products.map(function (p, i) {
  return (i + 1) + '. ' + p.name + '\n   Description: ' + (p.description || 'N/A') + '\n   Key features: ' + (Array.isArray(p.features) ? p.features.join('; ') : (p.features || 'N/A'));
}).join('\n');
// Readable list of the selected products for the AI prompt.

return [{
  json: {
    proposalRef: proposalRef,
    dateStr: dateStr,
    company: company,
    user: user,
    products: products,
    requirementsInput: body.requirements || '',
    pricing: Array.isArray(body.pricing) ? body.pricing : [],
    recipientTitle: body.recipientTitle || 'IT Manager',
    productBlock: productBlock,
    researchText: toText(ctx.customerResearch, 3000),
    meetingText: toText(ctx.meetingPrep, 3000),
    recsText: toText(ctx.productRecommendations, 2500),
    sources: {
      provided: Object.keys(body.agentContext || {}),
      fetched: fetched,
      failed: failed
    }
  }
}];
// Everything the AI Agent and the Format Response node need, in one item.

