const prep = $('Gather Agent Data').first().json;
// The collected data and inputs from the first Code node.

let raw = $input.first().json.output || '';
// The AI Agent's text answer.

raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
// Remove markdown fences if the model added them.

let ai;
try {
  ai = JSON.parse(raw);
  // Normal case: the model returned clean JSON.
} catch (e) {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  // Fallback: find the outermost JSON object in the text.
  if (start === -1 || end === -1) throw new Error('Agent did not return valid JSON: ' + raw.substring(0, 200));
  // Nothing usable, so fail loudly instead of returning an empty proposal.
  ai = JSON.parse(raw.substring(start, end + 1));
}

const investment = prep.products.map(function (p, i) {
  // Prices come ONLY from the request, never from the AI.
  const price = prep.pricing.find(function (x) { return x.product === p.name; }) || prep.pricing[i] || {};
  return {
    description: p.name,
    speed: price.speed || 'To be confirmed',
    oneTimeCharge: price.oneTimeCharge != null ? price.oneTimeCharge : 'To be confirmed',
    monthlyRental: price.monthlyRental != null ? price.monthlyRental : 'To be confirmed'
  };
});

const names = prep.products.map(function (p) { return p.name; }).join(', ');
// Product names for the submission line.

const explanations = (Array.isArray(ai.productExplanations) ? ai.productExplanations : []).map(function (e) { return e.paragraph; }).filter(Boolean);
// One AI-written paragraph per selected product, taken from the knowledge base descriptions.

const letterParagraphs = [
  'We understand that every organisation needs to create an edge to succeed in the current complex business environment and how technology could help to achieve this. That is why we at SLT-MOBITEL have created a suite of customisable and scalable intelligent enterprise solutions designed to help you make that crucial leap to take your business beyond where it can be to where it should be.',
  // Fixed paragraph 1 from your template.
  'As we combine the strength of fixed and mobile, we pride ourselves on our unmatched enterprise capabilities and expert experience spanning decades. Moreover, we have dedicated Account Managers at your service, ensuring we are not only your provider but also your partner in progress.',
  // Fixed paragraph 2 from your template.
  ai.letterTailored || '',
  // Customer-specific paragraph built from the research, meeting prep and recommendation data.
  'We are pleased to submit the attached proposal for ' + names + '. Our proposal briefs on:',
  // Submission line with the selected products.
].concat(explanations).concat([
  'We look forward to discussing the proposal in detail. Do not hesitate to reach out to ' + (prep.user.name || 'your Account Manager') + (prep.user.phone ? ' on ' + prep.user.phone : '') + ' should you require any assistance.',
  // Contact line uses the logged-in user's name and phone.
  'We are committed to partnering with you in your journey to success and look forward to empowering your business with our intelligent business solutions.'
  // Fixed closing from your template.
]).filter(Boolean);

return [{
  json: {
    success: true,
    agent: 'Proposal',
    sources: prep.sources,
    proposal: {
      proposalRef: prep.proposalRef,
      date: prep.dateStr,
      customer: { name: prep.company.name, address: prep.company.address || prep.company.location || '' },
      contact: { name: prep.user.name || '', phone: prep.user.phone || '', designation: prep.user.designation || '', email: prep.user.email || '' },
      letter: {
        recipientTitle: prep.recipientTitle,
        salutation: 'Dear Sir/Madam',
        subject: 'Business Proposal for ' + prep.company.name,
        paragraphs: letterParagraphs,
        tailored: ai.letterTailored || '',
        productParagraphs: explanations
      },
      products: prep.products.map(function (p) { return { id: p.id || '', name: p.name }; }),
      // Same order as requirements, solutionTable, investment and letter.productParagraphs, so the backend can map them by index
      requirements: Array.isArray(ai.requirements) ? ai.requirements : [],
      solutionIntro: ai.solutionIntro || '',
      solutionTable: Array.isArray(ai.solutionTable) ? ai.solutionTable : [],
      investment: investment,
      notes: Array.isArray(ai.notes) ? ai.notes : [],
      commitmentNote: '1 Year commitment period will be applicable'
    }
  }
}];
// Final response: the frontend renders this into the template, lets the rep edit it, then exports the PDF.
